// 🚀 ETL ROBUSTO POS SIGA (PLANILHA DESORGANIZADA)

// helpers
const clean = v => (v ? v.toString().trim() : '');

const onlyNumbers = v => clean(v).replace(/\D/g,'');

// CPF (reconstrói mesmo quebrado)
const formatarCPF = v => {
  const num = onlyNumbers(v);
  if (!num) return '="00000000000"';
  return `="${num.padStart(11,'0').slice(-11)}"`;
};

const formatarCEP = v => {
  const num = onlyNumbers(v);
  return num.padStart(8,'0').slice(0,8);
};

const formatarTelefone = v => onlyNumbers(v);

const formatarValor = v => {
  if (!v) return '="0,00"';

  let n = v.toString().replace(',', '.');

  if (n.includes('E')) {
    n = Number(n);
  }

  let num = parseFloat(n);
  if (isNaN(num)) num = 0;

  return `="${num.toFixed(2).replace('.',',')}"`;
};

const formatarData = v => {
  if (!v) return '';
  const s = clean(v);

  if (/^\d{8}$/.test(s)) return s;

  return '';
};

// entrada
let inputData = $input.all().map(i => i.json);

// processamento
const output = inputData.map(row => {

  const values = Object.values(row);

  return {
    json: {

      // heurística por posição aproximada
      'NOME ALUNO': clean(values[0]),

      'CURSO': clean(values[1]),

      'MATRICULA': clean(values[2]),

      'CPF': formatarCPF(values.slice(3,7).join('')),

      'DATA VENCIMENTO': formatarData(values.find(v => /\d{8}/.test(v))),

      'ENDEREÇO': values.find(v => v && v.toString().includes('RUA')) || '',

      'CIDADE': values.find(v => v && v.toString().toUpperCase().includes('RIO')) || '',

      'BAIRRO': '',

      'CEP': formatarCEP(values.find(v => /\d{5}/.test(v))),

      'ESTADO': 'RJ',

      'TELEFONE': formatarTelefone(values[5]),

      'CELULAR': formatarTelefone(values[6]),

      'RESPONSÁVEL': values.find(v => v && v.toString().length > 10) || '',

      'REFERENCIA': '',

      'VALOR PARCELA': formatarValor(values[values.length - 2]),

      'EMAIL': ''

    }
  };

});

return output;

// === BEZERRA DE ARAÚJO — POS SIGA (AJUSTADO FINAL) ===

// 🔧 Funções auxiliares
const normalize = str => str ? str.toString().trim().toLowerCase() : '';

// ENDEREÇO → remove . , ; : e espaços duplicados
const limparEndereco = texto =>
  texto
    ? texto
        .toString()
        .replace(/[.,;:]/g, '')
        .replace(/\s+/g, ' ')
        .trim()
    : '';

const limparEmail = email =>
  email ? email.toString().replace(/['"]/g, '').trim() : '';

// CEP → somente números (remove traço e espaços)
const formatarCEP = cep =>
  cep ? cep.toString().replace(/\D/g, '') : '';

// ✅ CPF — 11 dígitos com zeros à esquerda (texto no Excel)
const formatarCPF = valor => {
  if (!valor) return '="00000000000"';
  const num = valor.toString().replace(/\D/g, '').trim();
  return `="${num.padStart(11, '0')}"`;
};

// 📅 Data — dd/mm/aaaa → aaaammdd
const formatarData = data => {
  if (!data) return '';
  const partes = data.toString().split('/');
  if (partes.length === 3) {
    const [dia, mes, ano] = partes;
    return `${ano}${mes.padStart(2, '0')}${dia.padStart(2, '0')}`;
  }
  const d = new Date(data);
  if (isNaN(d)) return '';
  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
};

// 💰 Valor — duas casas decimais com vírgula
const formatarValor = valor => {
  if (!valor) return '="0,00"';
  let num = parseFloat(
    valor.toString().replace(/[^\d,.-]/g, '').replace(',', '.')
  );
  if (isNaN(num)) return '="0,00"';
  return `="${num.toFixed(2).replace('.', ',')}"`;
};

// ☎️ TELEFONE / CELULAR — pega apenas o primeiro número
const formatarTelefone = valor => {
  if (!valor) return '';

  const primeiro = valor
    .toString()
    .split(/[\/|;,]/)[0]
    .trim();

  const num = primeiro.replace(/\D/g, '');
  return num ? `="\t${num}"` : '';
};

// 🧹 Remove linhas vazias e cabeçalhos
const limparLinhas = dados =>
  dados.filter(row =>
    Object.values(row).some(v => (v || '').toString().trim() !== '')
  );

// 🔍 Lê dados do input
let inputData = $input.all().map(i => i.json);

// 🧱 Processamento principal
let saida = inputData.map(row => ({
  MATRICULA: row['MATRÍCULA'] || '',
  'NOME ALUNO': row['Aluno'] || '',
  'CURSO': row['Curso'] || '',
  'CPF': formatarCPF(row['CPFAluno']),
  'DATA NASCIMENTO': '', // Coluna E vazia
  'ENDEREÇO': limparEndereco(row['EnderecoResp. financeiro']),
  'BAIRRO': row['Bairro'] || '',
  'CIDADE': row['Cidade'] || '',
  'CEP': formatarCEP(row['CEP']),
  'ESTADO': row['Estado'] || '',
  'TELEFONE': formatarTelefone(row['TelefoneResp. financeiro']),
  'CELULAR': formatarTelefone(row['CelularResp. financeiro']),
  'RESPONSÁVEL': row['Resp. financeiro'] || '',
  'REFERENCIA': row['Referência'] || '',
  'DATA VENCIMENTO': formatarData(row['Vencimento']),
  'VALOR PARCELA': formatarValor(row['Valor integral']),
  'EMAIL': limparEmail(row['E-mailResp. financeiro'])
}));


// 🧼 Remove cabeçalho e linhas vazias
return limparLinhas(saida);
